
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_gga_xc_lc_wpbe_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_xc_lc_wpbe", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.132312903523996e+00, -4.049977028025516e+00, -3.934741357411728e+00, -3.775400218819689e+00, -3.558888833696036e+00, -3.272010229400370e+00, -2.905340475804674e+00, -2.459519048568118e+00, -1.949852896451507e+00, -1.404127898853222e+00, -8.797024518963663e-01, -5.385132001405333e-01, -4.484331756751391e-01, -3.349324524921903e-01, -1.951435668814557e-01, -7.500126845756737e-02, -1.282188371516047e-02, -3.755043635196429e-04, -2.739835721796966e-06, -3.758855640340230e-09]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


